INSERT INTO `chatbot_intent` (`id`, `keyword`, `response`) VALUES
(1, 'sosial media', 'akun sosial media BPMP Provinsi NTB instagram @bpmpntb, youtube @bpmp_ntb, tiktok bpmpntb, facebook bpmpntb,\n'),
(6, 'layanan data dan informasi', '<p>Pemberian layanan Data Dan Informasi Mutu Pendidikan di BPMP Provinsi NTB<br />dilakukan melalui mekanisme penyampaian permohonan melalui Unit LayananTerpadu (ULT)<br />BPMP Provinsi NTB. Kemudian permohonan tersebut disampaikan ke Pejabat Pengelola<br />Informasi dan Dokumentasi (PPID) BPMP Provinsi NTB.</p>\r\n<p>Selanjutnya PPID BPMP Provinsi NTB memeriksa berkas permohonan untuk<br />disetujur. PPID Provinsi NTB memproses permohonan data dan informasi dengan<br />berkoordinasi dengan pengelola data dan informasi sesuai dengan permintaan. Data dan<br />informasi yang dimohon tersebut disampaikan ke pemohon, Selanjutnya berkas permohonan<br />disimpan sebagai dokumentasi.</p>'),
(7, 'revitalisasi sekolah', 'p><span style=\"font-weight: 400;\"><strong>Revitalisasi Sekolah</strong> merupakan Program Prioritas untuk meningkatkan akses layanan pendidikan dan kualitas pembelajaran di satuan pendidikan untuk mewujudkan layanan pendidikan bermutu untuk semua melalui penyediaan sarana dan prasarana esensial bagi pendidikan yang berkualitas, aman, dan nyaman.</span></p>\r\n<p><strong>Peran&nbsp;BPMP sebagai UPT:</strong></p>\r\n<p><span style=\"font-weight: 400;\">Koordinasi dengan pemda, pendampingan pelaksanaan, random sampling pelaksanaan revitalisasi sekolah</span></p>\r\n<p><span style=\"font-weight: 400;\">Untuk materi lengkapnya dapat diakses melalui tautan&nbsp;<a href=\"https://s.id/protas-bpmpntb\">https://s.id/protas-bpmpntb</a></span></p>'),
(8, 'digitalisasi pembelajaran', '<p><span style=\"font-weight: 400;\"><strong>Digitalisasi Pembelajaran</strong>&nbsp;merupakan Program&nbsp;</span>Peningkatan akses layanan pendidikan dan kualitas pembelajaran melalui program Digitalisasi untuk memenuhi kebutuhan sarana pembelajaran dan meningkatkan kualitas pembelajaran berbasis digital yang merata di seluruh Indonesia</p>\r\n<p><strong>Peran BPMP sebagai UPT:</strong></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Koordinasi dengan pemda, pendampingan pelaksanaan digitalisasi</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Pemanfaatan Rumah Pendidikan dalam Mendukung Pembelajaran pada satuan pendidikan</span></li>\r\n</ul>\r\n<p><span style=\"font-weight: 400;\">Untuk materi lengkapnya dapat diakses melalui tautan&nbsp;<a href=\"https://s.id/protas-bpmpntb\">https://s.id/protas-bpmpntb</a></span></p>'),
(9, 'sistem penerimaan murid baru (SPMB)', '<p><span style=\"font-weight: 400;\"><span style=\"font-weight: 600;\">Sistem Penerimaan Murid Baru (SPMB) </span> merupakan Program yang bertujuan agar pelaksanaan Penerimaan Siswa Baru dapat&nbsp;</span><span style=\"font-weight: 400;\">dilaksanakan secara </span><strong>objektif, transparan, akuntabel, </strong><span style=\"font-weight: 400;\">berkeadilan, dan tanpa diskriminasi.</span></p>\r\n<p><strong>Peran BPMP sebagai UPT:</strong></p>\r\n<ul>\r\n<li><span style=\"font-weight: 400;\">Pendampingan pemda dalam pelaksanaan SPMB termasuk dalam penetapan daya tampung</span></li>\r\n<li><span style=\"font-weight: 400;\">Menginformasikan kepada Dinas Pendidikan alasan penolakan pengajuan daya tampung melalui Manajemen Dinas</span></li>\r\n<li><span style=\"font-weight: 400;\">Memverifikasi dan memvalidasi usulan daya tampung dari Dinas Pendidikan</span></li>\r\n</ul>\r\n<p><span style=\"font-weight: 400;\">Untuk materi lengkapnya dapat diakses melalui tautan&nbsp;<a href=\"https://s.id/protas-bpmpntb\">https://s.id/protas-bpmpntb</a></span></p>'),
(10, 'Wajib Belajar 13 Tahun', '<p><strong>Wajib Belajar 13 Tahun&nbsp;</strong>merupakan Program yang bertujuan untuk mendukung&nbsp;<span style=\"font-weight: 400;\">Terwujudnya </span><strong>perluasan dan pemerataan akses pendidikan</strong><span style=\"font-weight: 400;\"> anak usia dini, dasar, dan menengah </span><strong>yang bermutu.</strong></p>\r\n<p>Implementasi Wajib Belajar menjadi kunci untuk memastikan seluruh anak Indonesia mendapatkan pendidikan yang bermutu</p>\r\n<p><span style=\"font-weight: 400;\">Target Wajar 13 tahun</span></p>\r\n<ul>\r\n<li><span style=\"font-weight: 400;\">Angka Kesiapan Sekolah</span></li>\r\n<li><span style=\"font-weight: 400;\">APK PAUD&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Angka melanjutkan ke SM</span></li>\r\n<li><span style=\"font-weight: 400;\">Angka menamatkan SM</span></li>\r\n<li><span style=\"font-weight: 400;\">Perbandingan APK pada</span><span style=\"font-weight: 400;\"><br /></span><span style=\"font-weight: 400;\">SES 20% tertinggi dan terendah</span></li>\r\n</ul>\r\n<p><span style=\"font-weight: 400;\"><strong>BPMP </strong>berperan sebagai penggerak dan mitra strategis yang menjembatani kolaborasi, membangun sinergi, dan mendampingi pemerintah daerah dalam menjawab tantangan pendidikan di wilayahnya.</span></p><p><span style=\"font-weight: 400;\">Untuk materi lengkapnya dapat diakses melalui tautan&nbsp;<a href=\"https://s.id/protas-bpmpntb\">https://s.id/protas-bpmpntb</a></span></p>'),
(11, 'Penguatan Pendidikan Karakter', '<p><strong>Program Pembinaan Peserta Didik</strong> meliputi:</p>\r\n<p><span style=\"font-weight: 600;\">Usaha Kesehatan Sekolah (UKS)</span></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Meningkatnya kapasitas dan peran Tim Pembina &amp; Tim pelaksana UKS</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Meningkatnya Kesehatan Sekolah dan Kesehatan Peserta Didik</span></li>\r\n</ul>\r\n<p><span style=\"font-weight: 600;\">Gerakan 7 Kebiasaan Anak Indonesia Hebat&nbsp;&nbsp;</span></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Terlaksananya 7 Kebiasaan Anak Indonesia hebat pada peserta didik dalam kehidupan sehari-hari</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Meningkatnya Kesehatan, kecerdasan dan karakter peserta didik</span></li>\r\n</ul>\r\n<p><span style=\"font-weight: 600;\">Kepanduan &amp; Ekstrakurikuler Lainnya</span></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">meningkatnya tatakelola kegiatan ekstrakurikuler</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Berkembangnya potensi kepemimpinan, bakat, minat dan berbagai potensi peserta didik </span></li>\r\n</ul>\r\n<p><span style=\"font-weight: 400;\"><span style=\"font-weight: 600;\">Sekolah Aman, Nyaman dan Menggembirakan </span></span></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Meningkatkan manajemen dan tatakelola sekolah yang aman, nyaman, dan mencerdaskan</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Berkembangnya potensi, kecerdasan dan karakter peserta didik secara maksimal</span></li>\r\n</ul>\r\n<p><span style=\"font-weight: 600;\">Kemitraan dalam Pembinaan Peserta Didik</span></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Meningkatkan Kerjasama lintas K/L dan stakeholder terkait</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Meningkatnya peran mitra secara maksimal</span></li>\r\n</ul>\r\n<p><span style=\"font-weight: 600;\">Program Pendukung&nbsp;</span><span style=\"font-weight: 600;\">(Program Internalisasi)</span></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Meningkatnya motivasi kepala sekolah, guru, siswa, dan stakeholder terkait&nbsp; dalam melaksanakan Penguatan Pendidikan Karakter</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Diperolehnya SDM Duta-Duta Penguatan Pendidikan Karakter</span></li>\r\n</ul>\r\n<p><span style=\"font-weight: 400;\">Untuk materi lengkapnya dapat diakses melalui tautan&nbsp;<a href=\"https://s.id/protas-bpmpntb\">https://s.id/protas-bpmpntb</a></span></p>'),
(12, 'Makan Bergizi Gratis', '<p><strong>Program MBG</strong>&nbsp;di Satuan Pendidikan implementasinya didukung oleh Kemendikdasmen dan Kemenkes dengan BGN sebagai&nbsp;<em>leading sector.</em></p>\r\n<p><strong>Kemendikdasmen dan UPT</strong>&nbsp;Mendukung melalui kebijakan dalam hal:</p>\r\n<p>Pemenuhan kesiapan Satuan Pendidikan dan memastikan proses sosialisasi dan edukasi kesehatan terlaksana, serta mengukur evaluasi proses, luaran, dan dampak dari pada&nbsp;<strong>Program MBG</strong></p>\r\n<p>sedangkan untuk&nbsp;<strong>Pemda dan Dinas Pendidikan Prov., Kab./Kota&nbsp;</strong>mendukung melalui kebijakan dalam hal kesiapan dan persiapan satuan pendidikan dalam program MBG, dan menjalankan supervisi dan evaluasi pelaksanaan program MBG di Satuan Pendidikan dan melaporkannya kepada&nbsp;<strong>Kemendikdasmen</strong></p>\r\n<p><span style=\"font-weight: 400;\">Untuk materi lengkapnya dapat diakses melalui tautan&nbsp;<a href=\"https://s.id/protas-bpmpntb\">https://s.id/protas-bpmpntb</a></span></p>'),
(13, 'Pembelajaran dan Penilaian', '<p><strong>Program Pembelajaran dan Penilaian&nbsp;</strong>meliputi:</p>\r\n<p><strong>Pembelajaran Mendalam dan Penguatan Litnum</strong></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Sosialisasi Pembelajaran Mendalam ke Pemda</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Advokasi Pembelajaran Mendalam dan Penguatan Litnum melalui STEAM</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Visitasi/monitoring implementasi Pembelajaran Mendalam</span></li>\r\n</ul>\r\n<p><span style=\"font-weight: 400;\"><strong>Pembelajaran Koding dan KA</strong></span></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Seleksi Lembaga Penyelenggara Diklat (LPD)</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Benchmarking Praktik Pembelajaran Koding dan KA di Sekolah</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Pengembangan Portal Seleksi LPD</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Visitasi/ Monitoring Implementasi Pembelajaran Koding &amp; KA</span></li>\r\n</ul>\r\n<p><span style=\"font-weight: 400;\"><strong>Pengelolaan Ijazah Th 2025</strong></span></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Coaching clinic Residu Data Penerima Ijazah</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Sosialisasi Pedoman Pengelolaan Ijazah Th 2025</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Bimbingan Teknis Aplikasi e-Ijazah</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Pemantauan Pengelolaan Ijazah Th 2025</span></li>\r\n</ul>\r\n<p><span style=\"font-weight: 400;\"><strong>Tes Kemampuan Akademik</strong></span></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Sosialisasi Kebijakan TKA&nbsp;</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Supervisi Persiapan dan Pelaksanaan TKA Th 2025</span></li>\r\n</ul>\r\n<p><span style=\"font-weight: 400;\">Untuk materi lengkapnya dapat diakses melalui tautan&nbsp;<a href=\"https://s.id/protas-bpmpntb\">https://s.id/protas-bpmpntb</a></span></p>'),
(14, 'Pembelajaran Mendalam atau Deep Learning', '<p><span style=\"font-weight: 400;\">Pembelajaran Mendalam merupakan pendekatan yang </span><em><span style=\"font-weight: 900;\">memuliakan</span></em> <span style=\"font-weight: 400;\">dengan menekankan pada penciptaan suasana belajar dan proses pembelajaran </span><em><span style=\"font-weight: 900;\">berkesadaran</span></em><span style=\"font-weight: 400;\">, </span><em><span style=\"font-weight: 900;\">bermakna</span></em><span style=\"font-weight: 400;\">, dan </span><em><span style=\"font-weight: 900;\">menggembirakan</span></em> <span style=\"font-weight: 400;\">melalui </span><em><span style=\"font-weight: 900;\">olah pikir</span></em><span style=\"font-weight: 400;\">,</span> <em><span style=\"font-weight: 900;\">olah hati</span></em><span style=\"font-weight: 400;\">,</span><em><span style=\"font-weight: 900;\"> olah rasa</span></em><span style=\"font-weight: 400;\">,</span> <span style=\"font-weight: 400;\">dan </span><em><span style=\"font-weight: 900;\">olah raga</span></em><span style=\"font-weight: 400;\"> secara holistik dan terpadu.</span></p>\r\n<p><span style=\"font-weight: 400;\">Untuk materi lengkapnya dapat diakses melalui tautan&nbsp;<a href=\"https://s.id/protas-bpmpntb\">https://s.id/protas-bpmpntb</a></span></p>'),
(15, 'Pembelajaran Koding & KA', '<p><span style=\"font-weight: 400;\">Pembelajaran Koding dan Kecerdasan Artifisial (KA) bertujuan untuk mempersiapkan peserta didik menguasai konsep dan kompetensi tertentu sesuai tahapan perkembangannya.</span></p>\r\n<p><span style=\"font-weight: 400;\">Untuk materi lengkapnya dapat diakses melalui tautan&nbsp;<a href=\"https://s.id/protas-bpmpntb\">https://s.id/protas-bpmpntb</a></span></p>'),
(16, 'Penjaminan Mutu', '<p><strong>Kemendikdasmen </strong>bermitra dengan pemerintah daerah terlibat langsung dalam&nbsp;upaya supervisi dan fasilitasi peningkatan mutu di satuan pendidikan</p>\r\n<p><strong>Peranan pemerintah daerah dalam penjaminan mutu pendidikan</strong></p>\r\n<ol>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Mendorong partisipasi aktif dalam pemetaan mutu&nbsp;</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Melakukan koordinasi dan integrasi perencanaan daerah dengan satuan pendidikan</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Fasilitasi peningkatan mutu oleh pemerintah daerah (guru, sarana dan prasarana, serta pendanaan) melalui perencanaan daerah</span></li>\r\n</ol>\r\n<p><strong>Peran Strategis BBPMP/BPMP</strong></p>\r\n<ul>\r\n<li>\r\n<p><strong>Mengedukasi </strong><span style=\"font-weight: 400;\">penggunaan standar nasional pendidikan (SNP) sebagai acuan mutu satuan pendidikan</span></p>\r\n</li>\r\n<li>\r\n<p><span style=\"font-weight: 400;\">Bekerja sama dengan pemerintah daerah dalam </span><strong>memetakan </strong><span style=\"font-weight: 400;\">permasalahan pendidikan sesuai dengan SNP</span></p>\r\n</li>\r\n<li>\r\n<p><span style=\"font-weight: 400;\">Menjadi </span><strong>mitra pemerintah daerah</strong><span style=\"font-weight: 400;\"> dalam </span><strong>merencanakan dan melaksanakan </strong><span style=\"font-weight: 400;\">pemenuhan mutu sesuai standar nasional pendidikan, termasuk mengawal pemenuhan Standar Pelayanan Minimal (SPM)</span></p>\r\n</li>\r\n<li>\r\n<p><strong>Membangun kemitraan </strong><span style=\"font-weight: 400;\">dengan mitra pembangunan untuk mengakselerasi inovasi dan fasilitasi dalam penjaminan mutu pendidikan</span></p>\r\n</li>\r\n</ul>\r\n<p><span style=\"font-weight: 400;\">Untuk materi lengkapnya dapat diakses melalui tautan&nbsp;<a href=\"https://s.id/protas-bpmpntb\">https://s.id/protas-bpmpntb</a></span></p>'),
(17, 'sejarah bpmp ntb', '<p>Berdasarkan Peraturan Menteri Pendidikan Nasional No. 7 Tahun 2007 tentang organisasi dan tata kerja lembaga penjaminan mutu pendidikan, maka LPMP berubah dari Lembaga Penjamin Mutu Pendidikan&nbsp; menjadi Lembaga Penjaminan Mutu Pendidikan. Selanjutnya, berdasarkan Peraturan Menteri Pendidikan, Kebudayaan, Riset dan Teknologi No. 11 Tahun 2022 tentang organisasi dan tata kerja balai penjaminan mutu pendidikan, maka LPMP berubah dari Lembaga Penjaminan Mutu Pendidikan&nbsp; menjadi Balai Penjaminan Mutu Pendidikan.</p>\n<p>untuk selengkapnya mengenai sejarah BPMP NTB silahkan mengakses <a href=\"https://bpmpntb.kemendikdasmen.go.id/sejarah\">https://bpmpntb.kemendikdasmen.go.id/sejarah</a></p>\n<p>&nbsp;</p>'),
(18, 'pelaporan keluhan ', '<p>untuk melakukan pelaporan atau pertanyaan kepada Admin, silahkan bisa langsung mengetik <strong>admin </strong>atau<strong> hubungi admin</strong></p>'),
(19, 'Layanan sarana dan prasarana', '<p>Pemberian Pelayanan peminjaman sarana pras ana di BPMP Provinsi NTB dilakukan<br />melalui mekanisme penyampaian permohonan kepada Kepala BPMP Provinsi NTB melalui<br />Unit Layanan Terpadu (ULT) BPMP Provinsi NTB. Kemudian permohonan tersebut<br />disampaikan ke Kepala BPMP Provinsi NTB untuk didisposisikan kepada Kepala Sub Bagian<br />Umum untuk mencermati permohonan tersebut.</p>\r\n<p><br />Selanlutnya Kepala Sub Bagian Umum mengkoordinasikan permohonan tersebut<br />bersama Koordinator Urusan Humas, Tatalaksana dan Kerumahtanggaan BPMP Provinsi<br />NTB untuk melakukan pengecekan ketersediaan fasilitas. Urusan Kerumahtanggaan<br />menyampaikan informasi/surat balasan persetujuan peminjaman dan menyiapkan fasilitas<br />yang akandipinjam. Selanjutnya Petugas mencatat data pelanggan dan fasilitas yang dipinjam,<br />setelah pemohon menggunakan fasilitas pemohon menyelesaikan administrasi peminjaman.<br />Penggunaan fasilitas sesuai jadwal yang diajukan.</p>\r\n<p>Selain itu BPMP Provinsi NTB juga telah mengembangkan aplikasi SiPedas (Sistem Informasi Peminjaman sarana Dan prASarana) dimana pemohon dapat langsung melakukan peminjaman secara online melalui tautan <a href=\"https://bpmpntb.kemendikdasmen.go.id/pinjam-sarpras\">https://bpmpntb.kemendikdasmen.go.id/pinjam-sarpras</a></p>'),
(20, 'struktur organisasi bpmp ntb;struktur organisasi;organisasi bpmp;struktur bpmp;susunan organisasi bpmp;pimpinan bpmp ntb', '<b>Struktur Organisasi BPMP Provinsi Nusa Tenggara Barat</b><br> <ol> <li><b>Kepala BPMP NTB</b>: Katman, S.Pd., M.A.</li> <li><b>Kepala Subbagian Umum</b>: Hj. Lielies Miningrum, S.E</li> <li><b>Kelompok Jabatan Fungsional</b></li> <li><b>Jabatan Pelaksana</b></li> </ol> <i>Berdasarkan Peraturan Menteri Pendidikan, Kebudayaan, Riset, dan Teknologi nomor 11 Tahun 2022</i>'),
(22, 'penanggung jawab kemitraan 2025, PIC Progam BPMP NTB', 'Widyaprada Ahli Muda — Digitalisasi Pembelajaran\n\nDrs. Ma Min Shen, M.Pd. — Perencanaan Berbasis Data (PBD)\n\nYulia Hidayati, S.Pd., M.E. — Pembelajaran Mendalam\n\nBilly Fabiar, S.Kom — Coding AI\n\nMuhamad Hari Nurhadi, S.Si., M.Pd. — Persiapan Tes Kemampuan Akademik (TKA) dan Asesmen\n\nYuda Purwaka, S.Pd, M.Or. — Sosialisasi Aplikasi E-Rapor\n\nMusmuliadi, S.Si., M.Pd — Penanaman 7 Kebiasaan Indonesia Hebat\n\nI Ketut Budiarthi, SKM — Pendampingan Pelaksanaan Makan Bergizi Gratis (MBG)\n\nHusaini, M.Pd — Ekstrakurikuler\n\nMuhammad Idrus, M.Ag — (Tugas tidak tercantum, dapat diisi sesuai kebutuhan)\n\nHj. Lilis Sulianita, S.Pd., M.M. — Pembinaan Unit Kesehatan Sekolah (UKS)\n\nErnie Isis Aisyah Amini, M.Pd. — Sistem Penerimaan Murid Baru (SPMB)\n\nDr. Syamsul Hadi, M.Pd. — Wajar 13 Tahun dan Anak Tidak Sekolah (ATS)\n\nHizbul Maududi, S.S. — Pendidikan Kesetaraan (Paket A, B, C)\n\nAnggaraini Naskawati, M.Pd — Pendampingan Peningkatan Penjaminan Mutu Pendidikan\n\nTakyudin, S.Pd., M.Pd. — Pencegahan dan Penanganan Kekerasan di Satuan Pendidikan\n\nRustam Effendi, S.Kom., M.T. — Pemetaan Penggunaan Rapor Pendidikan dan SPMP\n\nAkhmad Sudirman, S.Si., M.Ed. — Pendampingan Pemda dalam Perencanaan Perbaikan dan Peningkatan Mutu Berkelanjutan\n\nH. Selamet Riyadi, S.Pd, M.Pd. — Pemantauan dan Evaluasi Peningkatan Mutu Pendidikan'),
(24, 'data sekolah ntb, jumlah sekolah di ntb, rekap sekolah ntb, total sekolah ntb, sekolah per kabupaten ntb', '<p>Berikut adalah rekap jumlah satuan pendidikan (sekolah dan lembaga) di Provinsi Nusa Tenggara Barat (NTB) berdasarkan data terakhir:</p>\r\n<p>Terdapat **total 10.873 satuan pendidikan** yang tersebar di seluruh kabupaten/kota di NTB, dengan rincian sebagai berikut:</p>\r\n<p>1. **Kabupaten Bima:** <br /> - PAUD: 770 <br /> - PKBM: 63 <br /> - SD: 426 <br /> - SKB: 1 <br /> - SLB: 13 <br /> - SMA: 54 <br /> - SMK: 33 <br /> - SMP: 135 <br /> - **Total:** 1.495</p>\r\n<p>2. **Kabupaten Dompu:** <br /> - PAUD: 310 <br /> - PKBM: 55 <br /> - SD: 231 <br /> - SKB: 1 <br /> - SLB: 9 <br /> - SMA: 29 <br /> - SMK: 24 <br /> - SMP: 73 <br /> - **Total:** 732</p>\r\n<p>3. **Kabupaten Lombok Barat:** <br /> - PAUD: 582 <br /> - PKBM: 55 <br /> - SD: 376 <br /> - SKB: 1 <br /> - SLB: 3 <br /> - SMA: 40 <br /> - SMK: 46 <br /> - SMP: 112 <br /> - **Total:** 1.215</p>\r\n<p>4. **Kabupaten Lombok Tengah:** <br /> - PAUD: 1.003 <br /> - PKBM: 77 <br /> - SD: 634 <br /> - SKB: 1 <br /> - SLB: 5 <br /> - SMA: 81 <br /> - SMK: 79 <br /> - SMP: 231 <br /> - **Total:** 2.111</p>\r\n<p>5. **Kabupaten Lombok Timur:** <br /> - PAUD: 1.097 <br /> - PKBM: 49 <br /> - SD: 792 <br /> - SKB: 1 <br /> - SLB: 8 <br /> - SMA: 87 <br /> - SMK: 101 <br /> - SMP: 289 <br /> - **Total:** 2.424</p>\r\n<p>6. **Kabupaten Lombok Utara:** <br /> - PAUD: 206 <br /> - PKBM: 17 <br /> - SD: 164 <br /> - SKB: 1 <br /> - SLB: 3 <br /> - SMA: 15 <br /> - SMK: 14 <br /> - SMP: 48 <br /> - **Total:** 468</p>\r\n<p>7. **Kabupaten Sumbawa:** <br /> - PAUD: 617 <br /> - PKBM: 32 <br /> - SD: 378 <br /> - SKB: 1 <br /> - SLB: 3 <br /> - SMA: 28 <br /> - SMK: 22 <br /> - SMP: 116 <br /> - **Total:** 1.197</p>\r\n<p>8. **Kabupaten Sumbawa Barat:** <br /> - PAUD: 172 <br /> - PKBM: 5 <br /> - SD: 113 <br /> - SKB: 1 <br /> - SLB: 1 <br /> - SMA: 12 <br /> - SMK: 7 <br /> - SMP: 42 <br /> - **Total:** 353</p>\r\n<p>9. **Kota Bima:** <br /> - PAUD: 167 <br /> - PKBM: 28 <br /> - SD: 83 <br /> - SKB: 1 <br /> - SLB: 5 <br /> - SMA: 16 <br /> - SMK: 11 <br /> - SMP: 23 <br /> - **Total:** 334</p>\r\n<p>10. **Kota Mataram:** <br /> - PAUD: 243 <br /> - PKBM: 7 <br /> - SD: 180 <br /> - SKB: 1 <br /> - SLB: 4 <br /> - SMA: 37 <br /> - SMK: 20 <br /> - SMP: 52 <br /> - **Total:** 544</p>\r\n<p>**Rekap total per jenjang/sektor pendidikan di NTB:**<br />- **PAUD:** 5.167 <br />- **PKBM:** 388 <br />- **SD:** 3.377 <br />- **SKB:** 10 <br />- **SLB:** 54 <br />- **SMA:** 399 <br />- **SMK:** 357 <br />- **SMP:** 1.121</p>\r\n<p>**Grand Total:** 10.873 satuan pendidikan.</p>'),
