INSERT INTO `kegiatan` (`id_kegiatan`, `id_pegawai`, `unit_kerja_id`, `nama_kegiatan`, `rincian_kegiatan`, `dokumentasi_url`, `materi_url`, `panduan_url`, `laporan_url`, `surat_menyurat_url`, `tanggal_mulai`, `tanggal_selesai`, `flyer`, `template_biodata`, `peserta_ringkasan`, `total_peserta`, `metode_pembayaran`, `deskripsi`, `metode_pelaksanaan`, `status`, `created_by`, `created_at`, `updated_at`) VALUES
(6, 85, '001', 'Konsolidasi Daerah Pendidikan Dasar dan Menengah Tahun 2026', 'Terna  Konsolidasi  Daerah  Pendidikan Dasar  dan  Menengah Tahun  2026 adalah \"Memperkuat  Partisipasi  Semesta   Wujudkan   Pendidikan   Bermutu   untuk Semua\".  Dengan  tema  ini,  seluruh  peserta yang  terdiri  atas semua  pemangku kepentingan  pendidikan dasar  dan  menengah mensinergikan strategi  kedepan dalam  menyukseskan program-program  yang  mendukung peningkatan  kualitas dan pemerataan akses terhadap layanan pendidikan. Sejalan dengan tema Konsolidasi Nasional Pendidikan Dasar dan  Menengah tahun 2026, beberapa isu strategis  yang   menjadi  pokok  bahasan   adalah:  1)  Sistem  Penjaminan  Mutu (SPM),   2)   Wajib   Belajar  13   Tahun,   3)   Revitalisasi   Satuan   Pendidikan,   3) Digitalisasi  Pembelajaran, 3)  Sistem  Penerimaan  Murin  Baru (SPMB), 4)  Makan Bergizi  Gratis  (MBG),  5)  Tes  Kemampuan  Akademik  (TKA),  6)   Penguatan endidikan Karakter (7  KAIH), 8)  Pembelajaran  Mendalam,  Kading,  KKA  dan  9) DAPODIK.', 'https://awan.gdoank.my.id/index.php/s/Ho9iS4AHnbzE4ia', 'https://awan.gdoank.my.id/index.php/s/rt2R698CLaycgcM', 'https://awan.gdoank.my.id/index.php/s/kddSZpZfb7W2Bbp', 'https://awan.gdoank.my.id/index.php/s/mw5f9Cdfoezzzg2', 'https://awan.gdoank.my.id/index.php/s/fopn53JxHyqNAni', '2026-03-06', '2026-03-08', 'flyers/GeszNEuyxr8BBQ2Bj6B5EjoUzu3bXYpHKVgSnLqi.png', 'template_biodata/raqwiMilAP80tMZLIj82uoSnrFiVisRBsG8PZVxS.docx', 'Ketua Komisi V DPRD Provinsi, Rektor UNRAM, Rektor UIN Mataram, Kepala Dinas Pendidikan Provinsi NTB, Kepala Dinas Pendidikan Kab/Kota, Sekdis/Kabid Dinas Pendidikan Provinsi NTB, Sekdis/Kabid Dinas Pendidikan Kab/Kota, Koordinator Pengawas Dinas Pendidikan Provinsi/Kab/Kota, Kepala Bidang Pendidikan Dasar dan Menengah BAPPEDA Provinsi NTB, Kepala BAPPEDA Bidang Pendidikan Dasar dan Menengah, Ketua BAN PDM, Kepala Kanwil Kemenag Provinsi, Kepala Kantor Bahasa Provinsi NTB, Kepala DP3AKKB Provinsi NTB, Kepala Dinas Sosial Provinsi NTB, Kabid Pendidikan Madrasah Provinsi NTB, Ketua Majelis Dasmen Muhammadiyah, Ketua Ma’arif NU Provinsi NTB, Ketua PGRI Provinsi NTB, Ketua IGI Provinsi, Ketua IGTKI Provinsi, Ketua HIMPAUDI Provinsi, Ketua IGRA Provinsi, Ketua PKG Kota, Ketua KKKS, Ketua MKKS SMP, Ketua MKKS Provinsi, Kepala SKB Kota, Ketua Forum PKBM, Ketua APSI Provinsi NTB, Ketua IPI Provinsi NTB, Ketua KPPA, Ketua KPAD, Ketua HIMPSI, Ketua Pokja Bunda PAUD Provinsi, Ketua Pokja Bunda PAUD Kota, Media TVRI NTB, Media TV, Staf BPMP Provinsi Nusa Tenggara Barat', 105, 'tunai', 'Tema  Konsolidasi  Daerah  Pendidikan Dasar  dan  Menengah Tahun  2026 adalah \"Memperkuat  Partisipasi  Semesta   Wujudkan   Pendidikan   Bermutu   untuk Semua\".  Dengan  tema  ini,  seluruh  peserta yang  terdiri  atas semua  pemangku kepentingan  pendidikan dasar  dan  menengah mensinergikan strategi  kedepan dalam  menyukseskan program-program  yang  mendukung peningkatan  kualitas dan pemerataan akses terhadap layanan pendidikan. Sejalan dengan tema Konsolidasi Nasional Pendidikan Dasar dan  Menengah tahun 2026, beberapa isu strategis  yang   menjadi  pokok  bahasan   adalah:  1)  Sistem  Penjaminan  Mutu (SPM),   2)   Wajib   Belajar  13   Tahun,   3)   Revitalisasi   Satuan   Pendidikan,   3) Digitalisasi  Pembelajaran, 3)  Sistem  Penerimaan  Murid  Baru (SPMB), 4)  Makan Bergizi  Gratis  (MBG),  5)  Tes  Kemampuan  Akademik  (TKA),  6)   Penguatan Pendidikan Karakter (7  KAIH), 8)  Pembelajaran  Mendalam,  Koding,  KKA  dan  9) DAPODIK.', 'luring', 'draft', NULL, '2026-02-25 20:21:22', '2026-03-03 19:41:24'),
(8, 86, '001', 'Internalisasi kebijakan Program Prioritas Kemendikdasmen Tahun 2026', NULL, 'https://awan.gdoank.my.id/index.php/s/qDt23rZbrQZrCSz', 'https://awan.gdoank.my.id/index.php/s/FQTSkC2wm5wYRkG', NULL, 'https://awan.gdoank.my.id/index.php/s/7fCRcADyWQqKyb4', 'https://awan.gdoank.my.id/index.php/s/C8kpjygJm5gYQdS', '2026-02-12', '2026-03-14', NULL, NULL, NULL, 96, 'tunai', NULL, 'daring', 'selesai', NULL, '2026-03-01 18:58:41', '2026-03-03 01:41:50'),
(9, 75, '001', 'Penguatan Kepemimpinan dan Kolaborasi Tim Kerja', NULL, 'https://awan.gdoank.my.id/index.php/s/bQprBFynJn66kCs', 'https://awan.gdoank.my.id/index.php/s/MCAYiaWmfZjTpiH', 'https://awan.gdoank.my.id/index.php/s/4AsnPETBpS6Tx7r', 'https://awan.gdoank.my.id/index.php/s/ZAyfQiHDc4T2tC9', 'https://awan.gdoank.my.id/index.php/s/DFisbgjqppnP6FY', '2026-01-27', '2026-01-29', NULL, NULL, NULL, 44, 'transfer', 'Telah melaksanakan kegiatan Penguatan Kepemimpinan dan Kolaborasi Tim Kerja yang dilaksanakan pada tanggal 27 s.d 29 Januari 2026 di The Jayakarta Resort, Jl. Raya Senggigi No.4, Senteluk, Kec. Batu Layar, Kabupaten Lombok Barat, Nusa Tenggara Barat. Dengan Jumlah Peserta 44 orang', 'luring', 'selesai', NULL, '2026-03-01 21:21:19', '2026-03-03 01:41:54'),
(10, 83, '003', 'Sosialisasi TKA Kepada Pemda dan Pemangku Kepentingan', 'Sosialisasi dan pemaparan struktur TKA serta integrasinya dengan AN kepada Dinas Pendidikan Kabupaten/Kota dan Provinsi.', 'https://awan.gdoank.my.id/index.php/s/tKHQztL9xmGi3sq', 'https://awan.gdoank.my.id/index.php/s/id4wiaC8rzcpf4s', 'https://awan.gdoank.my.id/index.php/s/sdCfgBLxS7oS7zk', 'https://awan.gdoank.my.id/index.php/s/oBCsa4TH7WCdL7k', 'https://awan.gdoank.my.id/index.php/s/GTdtgstQgLMz2Kj', '2026-02-22', '2026-02-24', NULL, NULL, 'BPMP NTB 5 orang, Tim Teknis TKA dari Dinas Pendidikan Kab/Kota 20 orang, Tim Teknis dari Kemenag 20 orang dan Dinas Provinsi 2 orang', 47, 'tunai', 'BPMP melakukan kegiatan digitalisasi dengan tujuan memberikan data yang objektif, meningkatkan mutu pendidikan, memfasilitasi proses seleksi akademik ke jenjang lebih tinggi atau dunia kerja, serta memetakan kemampuan murid secara lebih akurat. Harapannya tercapai pemahaman komprehensif kepada Dinas Pendidikan Kab/Kota dan Provinsi mengenai struktur TKA dan integrasinya dengan AN, menjamin pelaksanaan TKA sesuai POS, memfasilitasi perolehan data akademik yang valid dan terukur, serta mendorong pemetaan tantangan dan solusi mitigasi di lapangan.', 'luring', 'selesai', 83, '2026-03-02 05:17:30', '2026-04-01 17:46:03'),
(15, 80, '002', 'Workshop Penyusunan Program Pokja Bunda PAUD', NULL, 'https://awan.gdoank.my.id/index.php/s/5d8CCeB8gW2z58Q', 'https://awan.gdoank.my.id/index.php/s/BSpzjq3ZxC97mMb', 'https://awan.gdoank.my.id/index.php/s/TPNGJZXtXyFk9Za', NULL, 'https://awan.gdoank.my.id/index.php/s/KXwLSrrRtWyeFBL', '2026-02-26', '2026-02-28', NULL, NULL, 'BPMP NTB, Pokja Provinsi Nusa Tenggara Barat, Pokja Kabupaten/Kota Se NTB, Dinas Pendidikan KabupatenKota Se NTB, IGTKI Nusa Tenggara Barat, HIMPAUDI NTB, dan IGRA NTB', 50, 'tunai', 'Kegiatan ini dilaksanakan dengan tujuan sebagai berikut.\n1.	Mengidentifikasi isu strategis dan kebutuhan layanan PAUD di daerah.\n2.	Menyusun prioritas program dan kegiatan Pokja.\n3.	Menyusun rencana aksi lengkap dengan indikator, target, waktu, dan penanggung jawab.;\n4.	Menyepakati mekanisme koordinasi dan monitoring pelaksanaan program', 'luring', 'selesai', NULL, '2026-03-03 17:40:27', '2026-03-03 18:17:32'),
(23, 42, '004', 'Advokasi Kebijakan Transfer Daerah', NULL, 'https://awan.gdoank.my.id/index.php/s/6H8yERmLiPnbqyz', 'https://awan.gdoank.my.id/index.php/s/aSbNxtsMXHzxtAK', 'https://awan.gdoank.my.id/index.php/s/PdACpBbCXxRaDjK', 'https://awan.gdoank.my.id/index.php/s/dBtB4dR6Qbzrj4s', 'https://awan.gdoank.my.id/index.php/s/TQdYyjRBnNd7Lcx', '2026-03-12', '2026-03-14', NULL, NULL, 'Dinas Pendidikan kabupaten/kota dan Provinsi serta Internal BPMP', 55, 'tunai', 'Melakukan Sosialisasi Regulasi Baru terkait tata kelola dana BOSP dengan sasaran operator dinas jenjang Paud, SD, SMP dan SM dari Dinas Pendidikan Provinsi/Kabupaten/Kota se-NTB', 'luring', 'selesai', NULL, '2026-03-07 19:48:19', '2026-05-06 23:20:28'),
(24, 80, '002', 'Sosialisasi Penanganan Anak Tidak Sekolah (ATS) dan Wajib Belajar 13 tahun', NULL, 'https://awan.gdoank.my.id/index.php/s/NaX85Q4WaDLE7Lc', 'https://awan.gdoank.my.id/index.php/s/4dNdkg8W3rTrbjA', 'https://awan.gdoank.my.id/index.php/s/BBMzYtTKiW59DMK', NULL, 'https://awan.gdoank.my.id/index.php/s/w9ZEFoJHLgwXFjE', '2026-03-12', '2026-03-14', NULL, NULL, 'Peserta terdiri dari Penanggung Jawab ATS 11 orang, Operator ATS 11 orang, perwakilan SKB 10 orang, dan Ketua MKKS 12 orang, dengan total 44 peserta.', 48, 'tunai', 'Kegiatan ini dilaksanakan dengan tujuan sebagai berikut.\n1.	Meningkatkan pemahaman para pemangku kepentingan terkait kebijakan dan strategi penanganan Anak Tidak Sekolah (ATS) serta implementasi program Wajib Belajar 13 Tahun. \n2.	Menyamakan persepsi dan memperkuat komitmen pemerintah daerah, satuan pendidikan, dan pemangku kepentingan lainnya dalam upaya penuntasan ATS. \n3.	Mendorong kolaborasi dan sinergi lintas sektor dalam mendukung perluasan akses layanan pendidikan bagi seluruh anak agar dapat mengikuti pendidikan minimal hingga jenjang menengah. \n4.	Mengidentifikasi langkah-langkah strategis yang dapat dilakukan oleh pemerintah daerah dan satuan pendidikan dalam percepatan penanganan ATS dan pencapaian Wajib Belajar 13 Tahun', 'luring', 'selesai', NULL, '2026-03-08 20:02:19', '2026-04-07 18:15:12'),
(42, 85, '001', 'Monitoring Pemanfaatan Bantuan Sarana Digitalisasi Digitalisasi Pembelajaran Tahun 2026', NULL, NULL, NULL, NULL, NULL, NULL, '2026-04-06', '2026-04-07', NULL, NULL, 'Satuan Pendidikan', 25, 'transfer', 'Kegiatan Monitoring Pemanfaatan Bantuan Sarana Digitalisasi Pembelajaran Tahun 2026 merupakan bagian dari upaya pemerintah dalam memastikan efektivitas pelaksanaan program digitalisasi pendidikan sebagaimana diamanatkan dalam Instruksi Presiden Nomor 7 Tahun 2025. Program ini berfokus pada pengadaan dan pemanfaatan perangkat laptop beserta kelengkapannya untuk mendukung proses pembelajaran di satuan pendidikan.\n\nSehubungan dengan hal tersebut, Balai Penjaminan Mutu Pendidikan (BPMP) Provinsi Nusa Tenggara Barat menugaskan tim untuk melaksanakan kegiatan monitoring dan evaluasi (monev) terhadap pemanfaatan bantuan tersebut di berbagai kabupaten/kota di wilayah NTB. Kegiatan ini dilaksanakan pada tanggal 5 s.d. 8 April 2026, meliputi wilayah Pulau Lombok, Kabupaten Sumbawa Barat, Sumbawa, Kabupaten Bima, Dompu, dan Kota Bima.\n\nMonitoring ini bertujuan untuk memastikan bahwa perangkat yang telah didistribusikan benar-benar diterima, berfungsi dengan baik, serta digunakan secara optimal dalam mendukung kegiatan belajar mengajar. Selain itu, kegiatan ini juga menjadi langkah preventif untuk mengidentifikasi berbagai kendala teknis di lapangan agar dapat segera ditindaklanjuti.\n\nDalam pelaksanaannya, tim juga melakukan verifikasi dan pendampingan kepada satuan pendidikan terkait pengisian instrumen yang telah disediakan oleh Kementerian Pendidikan Dasar dan Menengah melalui tautan yang telah ditentukan. Pengisian instrumen ini menjadi bagian penting dalam proses evaluasi nasional terhadap kualitas dan kebermanfaatan bantuan sarana digitalisasi pembelajaran.\n\nMelalui kegiatan ini, diharapkan seluruh bantuan perangkat digital dapat memberikan manfaat maksimal bagi peserta didik dan guru, serta mendukung peningkatan mutu pembelajaran di satuan pendidikan secara berkelanjutan.', 'luring', 'selesai', NULL, '2026-04-05 21:31:03', '2026-04-16 00:34:20'),
(43, 77, '005', 'Sosialisasi Penjaminan Mutu Pendidikan Sekolah Model PM dan KKA', NULL, 'https://awan.gdoank.my.id/index.php/s/mzDf3zojwd6QGoc', NULL, 'https://awan.gdoank.my.id/index.php/s/cMQzY8sZBLyAJyL', NULL, NULL, '2026-04-14', '2026-04-16', 'flyers/Fxd5D9UWbptG7gsHMzfshkGlw2AY7IC9utsOWaIN.jpg', NULL, 'PNS', 61, 'tunai', 'Menyosialisasikan kebijakan penjaminan mutu pendidikan sekolah model kepada satuan pendidikan serta Dinas Pendidikan kabupaten/kota dan provinsi.\r\nTujuan kegiatan ini adalah untuk memberikan penguatan kepada Dinas Pendidikan dalam mendampingi Sekolah Model dan pemetaan awal terhadap capaian Sekolah Model', 'luring', 'selesai', NULL, '2026-04-06 19:00:07', '2026-04-16 23:52:20'),
(44, 83, '003', 'Monitoring Pelaksanaan Tes Kemampuan Akademik Jenjang SMP', NULL, 'https://awan.gdoank.my.id/index.php/s/gbzy3ZnkpsBWzAs', NULL, NULL, NULL, 'https://awan.gdoank.my.id/index.php/s/RG7L2FcYdHK56MJ', '2026-04-05', '2026-04-07', NULL, NULL, 'Pegawai BPMP NTB', 10, 'transfer', 'Kegiatan Monitoring dan Evaluasi Pelaksanaan TKA Jenjang SMP/Sederajat Tahun 2026\nbertujuan untuk melakukan monitoring dan evaluasi pelaksanaan TKA jenjang SMP\nsederajat di masing-masing kabupaten/kota yang menjadi sampel sasaran.', 'luring', 'berjalan', NULL, '2026-04-06 23:20:15', '2026-04-06 23:23:58'),
(45, 86, '001', 'Survei Persepsi Publik Tahun 2026', NULL, NULL, NULL, NULL, NULL, NULL, '2026-04-09', '2026-04-09', NULL, NULL, 'Kepala Bidang SMA, Kepala Bidang PAUD/SD/SMP, Kepala Sekolah, Orang Tua Murid, Masyrakat Sekitar', 13, 'tunai', NULL, 'luring', 'draft', NULL, '2026-04-06 23:27:07', '2026-04-06 23:27:07'),
(46, 80, '002', 'Pendampingan Pemda Dalam Sistem Penerimaan Murid Baru tahun 2026', NULL, 'https://awan.gdoank.my.id/index.php/s/2y8cSfEo5CaQT8J', 'https://awan.gdoank.my.id/index.php/s/ETffGDzaqXkbY6z', 'https://awan.gdoank.my.id/index.php/s/9kNJxMxBNJY35pM', 'https://awan.gdoank.my.id/index.php/s/Ci6ci8sAqwQe9XD', 'https://awan.gdoank.my.id/index.php/s/W9LknMScz8XyNgL', '2026-04-09', '2026-04-10', NULL, NULL, NULL, 0, 'tunai', 'Dalam rangka mendukung dan memastikan kelancaran pelaksanaan program prioritas \nMenteri Pendidikan Dasar dan Menengah, khususnya terkait Sistem Penerimaan Murid \nBaru, Balai Penjaminan Mutu Pendidikan Nusa Tenggara Barat akan Pendampingan \nPemerintah Daerah dalam pelaksanaan SPMB Tahun 2026 khususnya terkait verifikasi dan \nvalidasi daya tampung satuan pendidikan dalam kondisi pengecualian, dengan strategi \nForum Group Disscusion (FGD)', 'luring', 'selesai', NULL, '2026-04-07 01:19:12', '2026-04-16 00:34:04'),
(47, 80, '002', 'Advokasi Kepada Pemda Dalam Rangka Pemberian Dukungan Kebijakan Wajib  Belajar 13 Tahun', NULL, 'https://awan.gdoank.my.id/index.php/s/aeQDefABbL7nNLr', 'https://awan.gdoank.my.id/index.php/s/ooZxfgjXf6nRXXY', 'https://awan.gdoank.my.id/index.php/s/cSsEJPKck5Fr9Er', 'https://awan.gdoank.my.id/index.php/s/wAPCaWAAefFKw27', 'https://awan.gdoank.my.id/index.php/s/CPeZq7cBTHDAf3p', '2026-04-22', '2026-04-23', NULL, NULL, 'Staf Dinas se 10 Kabupaten/kota dan Provinsi, BPMP NTB', 154, 'tunai', NULL, 'luring', 'berjalan', NULL, '2026-04-07 02:01:03', '2026-04-21 18:55:21'),
(48, 80, '002', 'Sosialisasi Regulasi Sistem Penerimaan Murid Baru     Kepada Pemda dan Pemangku Kepentingan', NULL, 'https://awan.gdoank.my.id/index.php/s/Gkg3Zj2szNxQZz2', 'https://awan.gdoank.my.id/index.php/s/aQmDa3Aeo9RioSM', 'https://awan.gdoank.my.id/index.php/s/n23S5kceyqFwLeN', 'https://awan.gdoank.my.id/index.php/s/MAJJ4wsQxXGRkWd', 'https://awan.gdoank.my.id/index.php/s/QXWAYnFcsFLBDTp', '2026-02-22', '2026-02-24', NULL, NULL, 'Dinas kabupaten/kota se provinsi NTB, BPMP NTB', 55, 'tunai', 'Dalam rangka mendukung dan memastikan kelancaran pelaksanaan program prioritas Menteri Pendidikan Dasar dan Menengah, khususnya terkait Sistem Penerimaan Murid Baru, Balai Penjaminan Mutu Pendidikan Nusa Tenggara Barat akan menyelenggarakan kegiatan Sosialisasi Regulasi Sistem Penerimaan Murud Baru Kepada Pemda dan Pemangku Kepentingan', 'luring', 'selesai', NULL, '2026-04-07 18:05:29', '2026-04-12 22:59:43'),
(49, 80, '002', 'Sosialisasi Panduan Pelaksanaan Gerakan 7 Kebiasaan Anak Indonesia Hebat', NULL, 'https://awan.gdoank.my.id/index.php/s/obw64yXGs7p52mt', 'https://awan.gdoank.my.id/index.php/s/7B4jGSqNQkyG2nG', 'https://awan.gdoank.my.id/index.php/s/xC8FrdxyQYt48GN', 'https://awan.gdoank.my.id/index.php/s/cPkRDe3RKZGoTQN', 'https://awan.gdoank.my.id/index.php/s/4sGzQs2NwNGYCnF', '2026-04-14', '2026-04-16', 'flyers/w7JaJff9jWp9f3TcmP0lvXkg4Eln2ktf1ZBFoeE3.jpg', NULL, 'Pengawas SD, SMP, SMA dan Tim Spesialis Peserta didik Se 10 Kabupaten/Kota, Dinas Provinsi NTB', 65, 'tunai', 'Menyongsong masa Indonesia Emas, pemerinntah telah meluncurkan program Gerakan 7 Kebiasaan Anak Indonesia Hebat (G7KAIH) dengan visi menciptakan generasi penerus bangsa yang sehat, cerdas, dan berkarakter unggul. Gerakan ini bertujuan untuk menanamkan kebiasaan positif sejak dini, sehingga anak-anak dapat tumbuh menjadi individu yang mandiri, kreatif, dan memiliki karakter kuat. G7KAIH dicanangkan karena banyaknya permasalahan komplek yang dihadapi oleh bangsa Indonesia, mulai dari kehidupan sosial, ekonomi politik, budaya, dan keamanan negara. Pendeknya banyak sekali permasalahan dalam kehidupan berbangsa dan bernegara pada saat ini', 'luring', 'selesai', NULL, '2026-04-10 03:55:19', '2026-04-16 00:33:25'),
(50, 77, '005', 'Pemetaan Mutu Pendidikan', NULL, 'https://awan.gdoank.my.id/index.php/s/wwZ24pHDCnSsnsZ', NULL, 'https://awan.gdoank.my.id/index.php/s/sqrQWHr87ifYKZS', NULL, 'https://awan.gdoank.my.id/index.php/apps/files/files/18050?dir=/PMP%20Lombok%20Plaza%2021%20s.d%20%2023%20April%202026/Surat-Surat', '2026-04-21', '2026-04-23', 'flyers/3jjxeTQ7pD2WwczMoTXeMTUqNBdZbV9fOLtLZabu.jpg', NULL, 'PNS', 50, 'tunai', 'Menyediakan gambaran kondisi mutu pendidikan di satuan pendidikan dan    daerah  sehingga dapat mengidentifikasi akar masalah yang mempengaruhi penurunan capaian SPM serta Rekomendasi program dan kegiatan yang terarah untuk peningkatan hasil belajar dan kualitas pembelajaran.', 'luring', 'selesai', NULL, '2026-04-15 01:21:13', '2026-04-22 19:51:07'),
(52, 42, '004', 'Pendampingan Penatausahaan Dana Transfer Daerah', NULL, NULL, NULL, NULL, NULL, NULL, '2026-04-21', '2026-04-22', NULL, NULL, 'Tenaga Fungsional dan Pelaksana BPMP NTB', 22, 'transfer', 'Kegiatan ini dilakukan untuk mengetahui gambaran pelaksanaan penatausahaan Dana Transfer Daerah oleh Pemerintah Daerah dan Satuan Pendidikan serta mendapatkan informasi tentang sejauhmana kepatuhan satuan pendidikan terhadap juknis pengelolaan BOSP selama ini', 'luring', 'selesai', NULL, '2026-04-19 03:55:24', '2026-05-06 23:22:33'),
(53, 95, '004', 'Pelatihan Integrasi Koding dan Kecerdasan Artifisial dalam Pembelajaran STEM Bagi Guru Jenjang SMP', NULL, 'https://awan.gdoank.my.id/index.php/s/ecf5CFt8CNtWbMo', NULL, NULL, NULL, NULL, '2026-04-28', '2026-04-30', 'flyers/HDGcshzhZ2tSrzIudlRb9ZV5HZpAP0WouLOjU5qf.png', NULL, 'Guru SMP Kota Mataram dan Lombok Barat', 40, 'tunai', 'Menindaklanjuti kerja sama antara Balai Penjaminan Mutu Pendidikan (BPMP)\r\nProvinsi Nusa Tenggara Barat dengan SEAMEO QITEP in Science (SEAQIS) dalam\r\nrangka peningkatan kompetensi guru, khususnya pada integrasi pembelajaran STEM\r\ndengan koding dan kecerdasan artifisial, dengan ini kami sampaikan bahwa akan\r\ndilaksanakan kegiatan Pelatihan Integrasi STEM dengan Koding dan Kecerdasan\r\nArtifisial dengan jumlah peserta sebanyak 40 orang Guru IPA SMP. Kegiatan akan\r\ndilaksanakan pada,\r\nhari, tangal : Selasa sd Kamis, 28 s.d. 30 April 2026\r\ntempat : BPMP NTB , Jl. Panji Tilarnegara No. 8. Mataram', 'luring', 'selesai', NULL, '2026-04-20 01:16:11', '2026-05-05 22:46:08'),
(54, 86, '001', 'ENNIKI', NULL, 'https://awan.gdoank.my.id/index.php/s/bFtfefypB6rk7Gm', NULL, NULL, NULL, NULL, '2026-04-23', '2026-04-23', NULL, NULL, NULL, 0, 'tunai', NULL, 'luring', 'selesai', NULL, '2026-04-23 20:01:14', '2026-04-26 05:13:50'),
(55, 83, '003', 'Diseminasi Praktek Baik Program Prioritas 2025', NULL, 'https://awan.gdoank.my.id/index.php/s/wzLAjFSdomj2MdD', 'https://drive.google.com/drive/folders/1YhztmEK02DgHGgPU01pXgAmFqLIgOpJf?usp=drive_link', NULL, NULL, 'https://awan.gdoank.my.id/index.php/s/6PcBqzNZ2ywNttD', '2026-04-28', '2026-04-30', NULL, NULL, 'Kepala Dinas, Kepala Bidang, Ketua KKKS SD, Ketua MKKS SMp, Ketua HIM PAUDI, MKKS SMA, Satuan Pendidikan Mitra, dan Cabang Dinas Kabupaten/kota', 114, 'tunai', 'Kegiatan ini bertujuan untuk menyebarluaskan hasil praktik baik implementasi program prioritas oleh satuan pendidikan. Forum ini juga sebagai wadah berbagi praktik baik dukungan pemerintah daerah, peran serta mitra atau komunitas dalam mengawal dan menyukseskan program prioritas Kemendikdasmen. Selain itu, kegiatan ini juga bertujuan untuk melakukan evaluasi dan refleksi pelaksanaan program prioritas Kemendikdasmen tahun 2025, meningkatkan koordinasi dan kolaborasi serta memberikan apresiasi kepada seluruh pemangku kepentingan atas partisipasi dan dukungan terhadap program prioritas Kemendikdasmen.', 'luring', 'draft', NULL, '2026-04-26 05:05:14', '2026-04-26 05:11:15'),
(56, 86, '001', 'Desiminasi BPMP Award', NULL, 'https://awan.gdoank.my.id/index.php/s/QxZdWiDMNJ5Njko', NULL, NULL, NULL, NULL, '2026-04-29', '2026-04-29', NULL, NULL, NULL, 150, 'tunai', 'Penganugrahan', 'luring', 'selesai', NULL, '2026-04-30 19:33:42', '2026-05-01 01:35:02'),
(57, 86, '001', 'BAYAN DESA LITERASI', NULL, 'https://awan.gdoank.my.id/index.php/s/a6mjxCcqza3pKir', NULL, NULL, NULL, NULL, '2026-04-30', '2026-04-30', NULL, NULL, NULL, 0, 'tunai', NULL, 'luring', 'selesai', NULL, '2026-05-01 01:28:29', '2026-05-01 01:33:39'),
(58, 77, '005', 'Pendampingan Perencanaan SPM Pendidikan Tahun 2026', NULL, 'https://awan.gdoank.my.id/index.php/s/Gys34ozT664M4FW', NULL, NULL, NULL, NULL, '2026-05-11', '2026-05-12', 'flyers/9N136pCYCun5JMYdtNJxDG7IP0OkRtT0dpVMGFFL.png', NULL, 'Dinas Pendidikan (bidang PAUD, SD, SMP, GTK, Perencanaan) BPMP NTB Bapeeda', 180, 'tunai', 'Pendampingan Perencanaan Berbasis Rapor Pendidikan untuk Pencapaian SPM dilaksanakan dengan metode Focus Group Discussion (FGD)\r\nRapor Pendidikan merupakan instrumen utama dalam mengidentifikasi capaian mutu pendidikan di daerah, baik pada aspek hasil belajar, proses pembelajaran, maupun layanan pendidikan. Di sisi lain, Standar Pelayanan Minimal (SPM) menjadi tolok ukur wajib yang harus dipenuhi oleh pemerintah daerah dalam memberikan layanan pendidikan.\r\nHasil Analisis Rapor Pendidikan yang telah dilaksanakan oleh BPMP bersama Dinas Pendidikan pada tanggal 21 April 2026 menunjukkan masih terdapat indikator yang belum mencapai target optimal oleh pemerintah daerah seperti rendahnya capaian literasi dan numerasi serta belum optimalnya Angka Partisipasi Sekolah (APS). Permasalahan tersebut perlu segera ditindaklanjuti melalui perencanaan yang tepat, terarah, dan berbasis data.\r\nDi samping itu pula perencanaan program dan kegiatan di daerah belum sepenuhnya mengacu pada hasil analisis Rapor Pendidikan. Oleh karena itu, diperlukan kegiatan pendampingan melalui Focus Group Discussion (FGD) yang melibatkan Dinas Pendidikan, narasumber dari BPMP, serta Bappeda untuk memastikan penyusunan rencana kerja yang selaras dengan kebutuhan peningkatan mutu pendidikan dan pencapaian SPM.', 'luring', 'selesai', NULL, '2026-05-05 18:40:40', '2026-05-17 18:39:58'),
(59, 80, '002', 'Pengembangan Strategi Implementasi Kebijakan Penuntasan Wajib Belajar 13 Tahun sesuai dengan Kondisi Daerah', NULL, 'https://awan.gdoank.my.id/index.php/s/TpiqngXn2MDegXQ', 'https://awan.gdoank.my.id/index.php/s/WBDL5s64kdAKmxW', 'https://awan.gdoank.my.id/index.php/s/ggYPXBNSWqDNnPx', 'https://awan.gdoank.my.id/index.php/s/8J5zPfizTjizj43', 'https://awan.gdoank.my.id/index.php/s/DdRdt4756EbkJXo', '2026-06-24', '2026-06-25', NULL, NULL, 'Dikbud Provinsi NTB, Dikbud Kab/Kota, DPMD, Dinas Sosial, Kemenag, Bappeda, PKBM', 110, 'tunai', 'Dalam rangka mendukung dan memastikan kelancaran pelaksanaan program prioritas Menteri Pendidikan Dasar dan Menengah, khususnya terkait implementasi Wajib Belajar 13 Tahun dan Penuntasan ATS (anak tidak sekolah), Balai Penjaminan Mutu Pendidikan Nusa Tenggara Barat akan melakukan Pengembangan strategi penuntasan Wajib Belajar yang sesuai dengan kondisi daerah dengan strategi Forum Group Disscusion (FGD)', 'luring', 'selesai', NULL, '2026-05-06 18:04:32', '2026-06-30 00:02:20'),
(60, 42, '004', 'Rapat Koordinasi dengan Pemerintah Daerah dalam Peningkatan  Akses Layanan Pendidikan melalui  Program Revitalisasi', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-18', '2026-05-20', 'flyers/3biGBBEnalB7pyRdHyRPizQryZojNKid6T1m3ob9.jpg', NULL, 'Pejabat Struktural Dinas Pendidikan, Pejabat Fungsional dan Pelaksana BPMP NTB', 60, 'tunai', 'Sasaran Peserta adalah BPMP NTB, Kabid Sarpras jenjang Paud/SD/SMP/SMA di Dinas Pendidikan Prov/Kab/Kota se- NTB dengan narasumber Perguruan Tinggi (UNRAM), Ditjen Pajak, dan Kejati Mataram', 'luring', 'selesai', NULL, '2026-05-06 23:38:17', '2026-05-20 19:25:09'),
(61, 85, '001', 'Verifikasi Validasi Data Pokok Pendidikan Tahun 2026', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21', '2026-05-22', NULL, NULL, 'Pendamping BPMP NTB dan Operator Dapodik Dinas', 0, 'tunai', 'Dalam rangka meningkatkan kualitas data pokok pendidikan, dipandang perlu adanya pendampingan verifikasi dan validasi data pokok pendidikan kepada satuan pendidikan.\nBerdasarkan dashboard Indeks Kualitas Dapodik tanggal 11 Mei 2026 (https://dapomart.kemendikdasmen.go.id/), total Indeks Kualitas Dapodik (IKD) Provinsi Nusa Tenggara Barat baru mencapai 76,68%, dimana dari 3 indikator IKD yaitu kelengkapan (87,03%), validitas (74,10%) dan mutakhir (69,77%) mengalami penurunan dibandingkan tahun sebelumnya. Menindaklanjuti hal tersebut, BPMP NTB akan melaksanakan kegiatan Verifikasi Validasi Data Pokok Pendidikan Tahun 2026 di 10 Kabupaten/Kota.', 'daring', 'draft', NULL, '2026-05-15 19:24:25', '2026-05-15 19:24:25'),
(74, 83, '003', 'Sosialisasi Sahabat Sekolah Dasar (Penguatan Gerakan 7 Kebiasaan Anak Indonesia Hebat)', NULL, 'https://awan.gdoank.my.id/index.php/s/fDNczY8N9JkSDA6', 'https://awan.gdoank.my.id/index.php/s/BtqsLgCy46zwK56', NULL, NULL, 'https://awan.gdoank.my.id/index.php/s/85bSxLyLTcFRaXP', '2026-05-20', '2026-05-26', NULL, NULL, 'Kepala Sekolah', 800, 'tunai', 'Program tersebut dimaksudkan untuk menunjang peningkatan mutu dan kualitas pendidikan dalam rangka mewujudkan pendidikan bermutu untuk semua.\nUntuk mendukung terwujudnya budaya sekolah yang aman dan nyaman tersebut, diperlukan pendekatan yang melibatkan murid secara aktif sebagai bagian dari perubahan. Salah satu upaya untuk melibatkan murid secara optimal dalam penguatan Pendidikan karakter, Direktorat Sekolah Dasar mencanangkan Program Sahabat Sekolah Dasar. Program Sahabat Sekolah Dasar bertujuan untuk mendorong terbentuknya budaya sekolah yang aman dan nyaman melalui penguatan karakter murid yang didukung oleh ekosistem pendidikan yang kolaboratif. Agar Program Sahabat Sekolah Dasar dapat dilaksanakan dengan baik oleh satuan pendidikan', 'luring', 'berjalan', NULL, '2026-05-17 22:18:30', '2026-05-25 00:22:49'),
(77, 95, '001', 'Koordinasi dengan pemda dalam peningkatan akses layanan pendidikan melalui program revitalisasi', NULL, NULL, 'https://awan.gdoank.my.id/index.php/s/s8WdimTqpjwrXyW', NULL, NULL, NULL, '2026-05-18', '2026-05-20', NULL, NULL, NULL, 0, 'tidak_dibayar', NULL, 'daring', 'draft', NULL, '2026-05-19 20:38:29', '2026-05-19 20:38:29'),
